//! Cargo-driven `wdfldr.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is wdfldr-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/sdk/lib/drivers/wdfldr",
        "sdk/lib/drivers/wdfldr",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/wdf/shared/inc/private/common",
        "vendor/wdf/kmdf/inc/private",
        "sdk/lib/drivers/wdf_reactos/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", 0x7ffb00000000u64),
        o => panic!("wdfldr-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:aux_klib", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:hal", "engine:chkstk", "engine:c:memcmp", "engine:cntpr_rust"],
        "x86_64" => &["body", "engine:c:aux_klib", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:hal", "engine:c:memcmp", "engine:cntpr_rust"],
        "aarch64" => &["body", "engine:c:aux_klib", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:hal", "engine:chkstk", "engine:c:memcmp", "engine:cntpr_rust"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("wdfldr-rust")
        .rust_user_target()
        .rc("sdk/lib/drivers/wdfldr/wdfldr.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("sdk/lib/drivers/wdfldr/wdfldr.spec", "wdfldr.sys")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
